import{_ as e,o,c as t,a2 as d}from"./chunks/framework.D8Tso2Ul.js";const p=JSON.parse('{"title":"Documentos obligatorios DS 44","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/documentos-obligatorios.md","filePath":"ds44/documentos-obligatorios.md"}'),i={name:"ds44/documentos-obligatorios.md"};function s(r,a,n,c,l,u){return o(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="documentos-obligatorios-ds-44" tabindex="-1">Documentos obligatorios DS 44 <a class="header-anchor" href="#documentos-obligatorios-ds-44" aria-label="Permalink to &quot;Documentos obligatorios DS 44&quot;">​</a></h1><p>El DS 44 exige que cada obra mantenga un conjunto de documentos vigentes y firmados. Build &amp; Serve los <strong>precrea automáticamente</strong> al crear una obra, según las fases configuradas para el tenant (<code>tenant.reglas.fasesObligatorias</code>). Cada documento queda clasificado, asignado a una fase y con su flujo de firma definido.</p><h2 id="catalogo-de-documentos" tabindex="-1">Catálogo de documentos <a class="header-anchor" href="#catalogo-de-documentos" aria-label="Permalink to &quot;Catálogo de documentos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Nombre</th><th>Fase típica</th><th>Quién firma</th><th>Obligatorio</th></tr></thead><tbody><tr><td><code>IRL</code></td><td>Informe de Riesgos Laborales</td><td>Todas</td><td>Prevencionista + Trabajador</td><td>✅</td></tr><tr><td><code>POLITICA_SSO</code></td><td>Política de Seguridad y Salud Ocupacional</td><td>Excavación (inicio)</td><td>Admin / Jefe de Obra</td><td>✅</td></tr><tr><td><code>REGLAMENTO_INTERNO</code></td><td>Reglamento Interno de Orden, Higiene y Seguridad</td><td>Excavación (inicio)</td><td>Trabajador (recepción)</td><td>✅</td></tr><tr><td><code>PROCEDIMIENTO_TRABAJO</code></td><td>Procedimiento de Trabajo Seguro</td><td>Obra gruesa</td><td>Supervisor + Trabajador</td><td>✅</td></tr><tr><td><code>ENTREGA_EPP</code></td><td>Acta de Entrega de EPP</td><td>Todas</td><td>Trabajador + Supervisor</td><td>✅</td></tr><tr><td><code>ENCUESTA_SALUD</code></td><td>Encuesta / Declaración de Salud</td><td>Excavación (ingreso)</td><td>Trabajador</td><td>✅</td></tr><tr><td><code>CAPACITACION_SST</code></td><td>Registro de Capacitación SST (Art. 16)</td><td>Todas</td><td>Relator + Asistentes</td><td>✅</td></tr><tr><td><code>MAPA_RIESGOS</code></td><td>Mapa de Riesgos de la obra</td><td>Obra gruesa</td><td>Prevencionista</td><td>✅</td></tr><tr><td><code>MIPPER</code></td><td>Matriz de Identificación de Peligros y Evaluación de Riesgos</td><td>Todas (por cargo)</td><td>Prevencionista</td><td>✅</td></tr></tbody></table><blockquote><p>Los códigos corresponden al campo <code>tipoDS44</code> de la tabla <code>DocumentosTable</code>. Consulta <a href="/manual/arquitectura/base-de-datos.html">Base de datos</a> para el esquema completo.</p></blockquote><h2 id="clasificacion-documentos-de-obra-vs-diarios" tabindex="-1">Clasificación: documentos de obra vs. diarios <a class="header-anchor" href="#clasificacion-documentos-de-obra-vs-diarios" aria-label="Permalink to &quot;Clasificación: documentos de obra vs. diarios&quot;">​</a></h2><p>Cada documento tiene un campo <code>clasificacion</code> que determina su comportamiento:</p><h3 id="documentos-de-obra-clasificacion-obra" tabindex="-1">Documentos de obra (<code>clasificacion: &quot;obra&quot;</code>) <a class="header-anchor" href="#documentos-de-obra-clasificacion-obra" aria-label="Permalink to &quot;Documentos de obra (`clasificacion: &quot;obra&quot;`)&quot;">​</a></h3><ul><li>Son los <strong>obligatorios por fase</strong> según el DS 44.</li><li>Se <strong>precrean</strong> al crear la obra, basándose en <code>fasesConfig</code>.</li><li>Accesibles desde la <strong>zona central de documentos</strong> de la obra.</li><li>Su cumplimiento se agrega por fase (porcentaje completado).</li><li>No se asignan individualmente: son documentos de referencia que deben existir y estar firmados para cumplir la normativa.</li></ul><h3 id="documentos-de-uso-diario-clasificacion-diario" tabindex="-1">Documentos de uso diario (<code>clasificacion: &quot;diario&quot;</code>) <a class="header-anchor" href="#documentos-de-uso-diario-clasificacion-diario" aria-label="Permalink to &quot;Documentos de uso diario (`clasificacion: &quot;diario&quot;`)&quot;">​</a></h3><ul><li>Se <strong>crean y asignan</strong> a personas específicas según necesidad.</li><li>Al asignarse, el <code>EventBus</code> emite <code>document.assigned</code> y genera una notificación en la bandeja de entrada de cada persona.</li><li>Aparecen como <strong>pendientes</strong> en el dashboard del trabajador.</li><li>Requieren <strong>firma individual</strong> (PIN o presencial).</li><li>Tienen fecha límite opcional; si vencen, su estado pasa a <code>vencido</code>.</li></ul><h2 id="estado-de-cumplimiento" tabindex="-1">Estado de cumplimiento <a class="header-anchor" href="#estado-de-cumplimiento" aria-label="Permalink to &quot;Estado de cumplimiento&quot;">​</a></h2><p>Cada documento avanza por los siguientes estados:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>borrador → activo → completado</span></span>\n<span class="line"><span>                  ↘ vencido (si pasa la fecha límite sin firmar)</span></span></code></pre></div><p>El cumplimiento de una fase se calcula como el porcentaje de documentos obligatorios de esa fase que se encuentran en estado <code>completado</code>. Al intentar <a href="/manual/ds44/fases-obra.html">avanzar de fase</a>, la plataforma verifica que la fase anterior esté completa.</p><div class="tip custom-block"><p class="custom-block-title">Generación asistida</p><p>La matriz <code>MIPPER</code> puede generarse con ayuda del <a href="/manual/modulos/asistente-ia.html">Asistente IA</a>, que propone peligros, riesgos y medidas de control por cargo a partir de la normativa vigente. El prevencionista revisa, ajusta y firma el resultado.</p></div>',16)])])}const b=e(i,[["render",s]]);export{p as __pageData,b as default};
